arguments.file_text:
@if (!IsVisible)
{
    <button class="btn btn-outline-primary btn-sm w-100" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="card mt-2">
        <div class="card-body p-2">
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="Title" />
            </div>
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="Assignee" />
            </div>
            <div class="mb-2">
                <select class="form-select form-select-sm" @bind="Priority">
                    <option value="High">High</option>
                    <option value="Medium">Medium</option>
                    <option value="Low">Low</option>
                </select>
            </div>
            <div class="mb-2">
                <input type="date" class="form-control form-control-sm" @bind="DueDate" />
            </div>
            <div class="d-flex gap-1">
                <button class="btn btn-primary btn-sm" @onclick="SaveAsync">Save</button>
                <button class="btn btn-secondary btn-sm" @onclick="Cancel">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool IsVisible;
    private string Title = "";
    private string Assignee = "";
    private string Priority = "Medium";
    private DateTime DueDate = DateTime.Today.AddDays(7);

    private void Show() => IsVisible = true;

    private void Cancel()
    {
        ResetForm();
        IsVisible = false;
    }

    private async System.Threading.Tasks.Task SaveAsync()
    {
        if (string.IsNullOrWhiteSpace(Title)) return;
        await OnTaskCreated.InvokeAsync(new TaskItem(0, Title, Assignee, Priority, DueDate, Status));
        ResetForm();
        IsVisible = false;
    }

    private void ResetForm()
    {
        Title = "";
        Assignee = "";
        Priority = "Medium";
        DueDate = DateTime.Today.AddDays(7);
    }
}

@page "/board"
@using sv_c3338f1fbf2d4ef99aa34db0113dd9bf.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error loading tasks:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Total="_filteredTasks.Count"
                   TodoCount="GetColumnTasks(TodoStatus).Count"
                   InProgressCount="GetColumnTasks(InProgressStatus).Count"
                   DoneCount="GetColumnTasks(DoneStatus).Count"
                   OverdueCount="_filteredTasks.Count(t => t.DueDate < DateTime.Today)" />

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchTerm" @bind:event="oninput" />
    </div>

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do" Status="@TodoStatus"
                      Tasks="GetColumnTasks(TodoStatus)"
                      CanMoveLeft="false" CanMoveRight="true"
                      OnMoveRight="@(id => MoveTaskAsync(id, InProgressStatus))"
                      OnTaskCreated="HandleTaskCreatedAsync" />

        <KanbanColumn ColumnName="In Progress" Status="@InProgressStatus"
                      Tasks="GetColumnTasks(InProgressStatus)"
                      CanMoveLeft="true" CanMoveRight="true"
                      OnMoveLeft="@(id => MoveTaskAsync(id, TodoStatus))"
                      OnMoveRight="@(id => MoveTaskAsync(id, DoneStatus))"
                      OnTaskCreated="HandleTaskCreatedAsync" />

        <KanbanColumn ColumnName="Done" Status="@DoneStatus"
                      Tasks="GetColumnTasks(DoneStatus)"
                      CanMoveLeft="true" CanMoveRight="false"
                      OnMoveLeft="@(id => MoveTaskAsync(id, InProgressStatus))"
                      OnTaskCreated="HandleTaskCreatedAsync" />
    </div>
}

@code {
    private const string TodoStatus = "To Do";
    private const string InProgressStatus = "In Progress";
    private const string DoneStatus = "Done";

    private List<TaskItem> _allTasks = new();
    private string _searchTerm = "";
    private bool _loading = true;
    private string? _error;

    private List<TaskItem> _filteredTasks =>
        string.IsNullOrWhiteSpace(_searchTerm)
            ? _allTasks
            : _allTasks.Where(t => t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> GetColumnTasks(string status) =>
        _filteredTasks.Where(t => t.Status == status).ToList();

    protected override async System.Threading.Tasks.Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async System.Threading.Tasks.Task LoadTasksAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async System.Threading.Tasks.Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                _allTasks = _allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async System.Threading.Tasks.Task HandleTaskCreatedAsync(TaskItem placeholder)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                placeholder.Title, placeholder.Assignee, placeholder.Priority, placeholder.DueDate);
            _allTasks.Add(created);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}

